package com.flippingmasterminds;

import javax.swing.*;
import java.awt.*;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.ExecutorService;

public class BuyLimitPanel extends JPanel
{
    private BuyLimitTracker buyLimitTracker;
    private Map<Integer, ItemMeta> meta;

    private JPanel listPanel;
    private final Timer refreshTimer;

    private final ConcurrentMap<Integer, ImageIcon> imageCache;
    private final Set<Integer> loadingSet;
    private final ExecutorService imageLoader;
    private final ImageIcon placeholderIcon;

    private static final int ICON_SIZE = 32;
    private static final long FOUR_HOURS_MS = 4 * 60 * 60 * 1000L;

    public BuyLimitPanel(ConcurrentMap<Integer, ImageIcon> imageCache,
                         Set<Integer> loadingSet,
                         ExecutorService imageLoader,
                         ImageIcon placeholderIcon)
    {
        this.imageCache      = imageCache;
        this.loadingSet      = loadingSet;
        this.imageLoader     = imageLoader;
        this.placeholderIcon = placeholderIcon;

        setLayout(new BorderLayout());

        // Header
        JPanel header = new JPanel(new FlowLayout(FlowLayout.LEFT, 8, 6));
        JLabel title = new JLabel("⏱ Buy Limit Cooldowns");
        title.setFont(title.getFont().deriveFont(Font.BOLD, 13f));
        header.add(title);

        JLabel subtitle = new JLabel("Active 4-hour GE buy limit windows");
        subtitle.setFont(subtitle.getFont().deriveFont(10f));
        subtitle.setForeground(Color.GRAY);
        header.add(subtitle);
        add(header, BorderLayout.NORTH);

        // Scrollable list
        listPanel = new JPanel();
        listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));

        JPanel wrapper = new JPanel(new BorderLayout());
        wrapper.add(listPanel, BorderLayout.NORTH);

        JScrollPane scroll = new JScrollPane(wrapper);
        scroll.setBorder(null);
        scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        JScrollBar vsb = scroll.getVerticalScrollBar();
        vsb.setPreferredSize(new Dimension(8, 0));
        vsb.setUnitIncrement(16);
        add(scroll, BorderLayout.CENTER);

        // Refresh every 30 seconds for accurate countdowns
        refreshTimer = new Timer(30_000, e -> rebuildList());
        refreshTimer.start();
    }

    public void stopTimer()
    {
        refreshTimer.stop();
    }

    public void setBuyLimitTracker(BuyLimitTracker tracker)
    {
        this.buyLimitTracker = tracker;
        rebuildList();
    }

    public void updateMeta(Map<Integer, ItemMeta> meta)
    {
        this.meta = meta;
        rebuildList();
    }

    void rebuildList()
    {
        listPanel.removeAll();

        if (buyLimitTracker == null)
        {
            addEmptyMessage("Tracker not ready.");
            return;
        }

        Map<Integer, Map<String, Object>> tracked = buyLimitTracker.getAllTracked();
        if (tracked.isEmpty())
        {
            addEmptyMessage("No active buy limits. Buy items on the GE to start tracking.");
            listPanel.revalidate();
            listPanel.repaint();
            return;
        }

        long now = System.currentTimeMillis();

        for (Map.Entry<Integer, Map<String, Object>> entry : tracked.entrySet())
        {
            int itemId  = entry.getKey();
            long firstBuy = (long) entry.getValue().get("firstBuyTimestamp");
            int  qty      = (int)  entry.getValue().get("quantityBought");

            long resetAt = firstBuy + FOUR_HOURS_MS;
            long msLeft  = resetAt - now;
            if (msLeft <= 0) continue;

            listPanel.add(makeLimitRow(itemId, qty, msLeft));
            listPanel.add(Box.createVerticalStrut(4));
        }

        if (listPanel.getComponentCount() == 0)
        {
            addEmptyMessage("All buy limits have reset.");
        }

        listPanel.revalidate();
        listPanel.repaint();
    }

    private JPanel makeLimitRow(int itemId, int qty, long msLeft)
    {
        long totalSeconds = msLeft / 1000;
        long hours   = totalSeconds / 3600;
        long minutes = (totalSeconds % 3600) / 60;
        long seconds = totalSeconds % 60;
        String timeStr = String.format("%dh %02dm %02ds", hours, minutes, seconds);

        // Progress bar value (0-100, how much time has passed)
        double progress = 1.0 - ((double) msLeft / FOUR_HOURS_MS);
        int progressPct = Math.min(100, Math.max(0, (int)(progress * 100)));

        String itemName = "Item " + itemId;
        if (meta != null && meta.containsKey(itemId))
        {
            itemName = meta.get(itemId).name;
        }

        JPanel row = new JPanel(new BorderLayout(8, 0))
        {
            @Override
            protected void paintComponent(Graphics g)
            {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setColor(new Color(30, 32, 42));
                g2.fillRoundRect(0, 0, getWidth(), getHeight(), 10, 10);
                g2.setColor(new Color(44, 47, 58));
                g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 10, 10);
                g2.dispose();
            }
        };
        row.setOpaque(false);
        row.setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 70));

        // Icon
        JLabel iconLbl = new JLabel();
        ImageIcon cached = imageCache.get(itemId);
        iconLbl.setIcon(cached != null ? cached : placeholderIcon);
        if (cached == null) scheduleIconLoad(itemId);
        row.add(iconLbl, BorderLayout.WEST);

        // Center text + progress bar
        JPanel center = new JPanel();
        center.setLayout(new BoxLayout(center, BoxLayout.Y_AXIS));
        center.setOpaque(false);

        String shortName = itemName.length() > 22 ? itemName.substring(0, 22) + "..." : itemName;
        JLabel nameLabel = new JLabel(shortName);
        nameLabel.setForeground(Color.WHITE);
        nameLabel.setFont(nameLabel.getFont().deriveFont(Font.BOLD, 12f));
        nameLabel.setToolTipText(itemName);
        center.add(nameLabel);

        JLabel infoLabel = new JLabel(qty + " bought  ·  resets in " + timeStr);
        infoLabel.setFont(infoLabel.getFont().deriveFont(10f));
        infoLabel.setForeground(new Color(150, 160, 190));
        center.add(infoLabel);

        // Progress bar showing time elapsed
        JProgressBar bar = new JProgressBar(0, 100);
        bar.setValue(progressPct);
        bar.setStringPainted(false);
        bar.setPreferredSize(new Dimension(0, 6));
        bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 6));
        bar.setForeground(new Color(80, 120, 200));
        bar.setBackground(new Color(45, 45, 55));
        bar.setBorderPainted(false);
        center.add(Box.createVerticalStrut(3));
        center.add(bar);

        row.add(center, BorderLayout.CENTER);

        return row;
    }

    private void addEmptyMessage(String text)
    {
        JPanel empty = new JPanel(new GridBagLayout());
        empty.setBorder(BorderFactory.createEmptyBorder(30, 10, 30, 10));
        JLabel emptyLabel = new JLabel(text);
        emptyLabel.setForeground(Color.GRAY);
        empty.add(emptyLabel);
        listPanel.add(empty);
    }

    private void scheduleIconLoad(int itemId)
    {
        if (meta == null) return;
        ItemMeta im = meta.get(itemId);
        if (im == null) return;
        FlippingMastermindsPanel.loadIconAsync(itemId, im.iconUrl, ICON_SIZE,
                imageCache, loadingSet, imageLoader, this::rebuildList);
    }
}

package com.flippingmasterminds;

import net.runelite.client.config.ConfigManager;

import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;

public class BuyLimitTracker
{
    private static final long FOUR_HOURS_MS = 4 * 60 * 60 * 1000L;

    private final ConfigManager configManager;
    private final Map<Integer, BuyRecord> records = new HashMap<>();

    public BuyLimitTracker(ConfigManager configManager)
    {
        this.configManager = configManager;
        load();
    }

    public synchronized void recordBuy(int itemId, int quantity)
    {
        BuyRecord record = records.get(itemId);

        if (record == null || record.isExpired())
        {
            record = new BuyRecord(System.currentTimeMillis(), quantity);
            records.put(itemId, record);
        }
        else
        {
            record.addQuantity(quantity);
        }

        save();
    }

    public synchronized Long getBuyTimestamp(int itemId)
    {
        BuyRecord record = records.get(itemId);
        if (record != null && !record.isExpired())
        {
            return record.getFirstBuyTimestamp();
        }
        return 0L;
    }

    public synchronized int getQuantityBoughtInWindow(int itemId)
    {
        BuyRecord record = records.get(itemId);
        if (record != null && !record.isExpired())
        {
            return record.getQuantityBought();
        }
        return 0;
    }

    public synchronized Map<Integer, Map<String, Object>> getAllTracked()
    {
        Map<Integer, Map<String, Object>> trackedData = new HashMap<>();

        Iterator<Map.Entry<Integer, BuyRecord>> iterator = records.entrySet().iterator();
        boolean removedAny = false;

        while (iterator.hasNext())
        {
            Map.Entry<Integer, BuyRecord> entry = iterator.next();
            BuyRecord record = entry.getValue();

            if (record.isExpired())
            {
                iterator.remove();
                removedAny = true;
            }
            else
            {
                Map<String, Object> itemData = new HashMap<>();
                itemData.put("firstBuyTimestamp", record.getFirstBuyTimestamp());
                itemData.put("quantityBought", record.getQuantityBought());
                trackedData.put(entry.getKey(), itemData);
            }
        }

        if (removedAny)
        {
            save();
        }

        return trackedData;
    }

    private static final String CONFIG_GROUP = "flippingmasterminds";
    private static final String CONFIG_KEY   = "buyLimitRecords";

    private void load()
    {
        String raw = configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY);
        if (raw == null || raw.isEmpty()) return;

        for (String entry : raw.split(";"))
        {
            String[] parts = entry.split(",");
            if (parts.length != 3) continue;
            try
            {
                int  itemId    = Integer.parseInt(parts[0]);
                long timestamp = Long.parseLong(parts[1]);
                int  qty       = Integer.parseInt(parts[2]);
                BuyRecord record = new BuyRecord(timestamp, qty);
                if (!record.isExpired())
                {
                    records.put(itemId, record);
                }
            }
            catch (NumberFormatException ignored) {}
        }
    }

    private void save()
    {
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<Integer, BuyRecord> entry : records.entrySet())
        {
            BuyRecord r = entry.getValue();
            if (r.isExpired()) continue;
            if (sb.length() > 0) sb.append(';');
            sb.append(entry.getKey()).append(',')
              .append(r.getFirstBuyTimestamp()).append(',')
              .append(r.getQuantityBought());
        }
        configManager.setConfiguration(CONFIG_GROUP, CONFIG_KEY, sb.toString());
    }

    private static class BuyRecord
    {
        private final long firstBuyTimestamp;
        private int quantityBought;

        public BuyRecord(long firstBuyTimestamp, int quantityBought)
        {
            this.firstBuyTimestamp = firstBuyTimestamp;
            this.quantityBought = quantityBought;
        }

        public long getFirstBuyTimestamp()
        {
            return firstBuyTimestamp;
        }

        public int getQuantityBought()
        {
            return quantityBought;
        }

        public void addQuantity(int quantity)
        {
            this.quantityBought += quantity;
        }

        public boolean isExpired()
        {
            return System.currentTimeMillis() - firstBuyTimestamp > FOUR_HOURS_MS;
        }
    }
}

package com.flippingmasterminds;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("flippingmasterminds")
public interface FlippingMastermindsConfig extends Config
{
	@ConfigItem(
			keyName = "apiToken",
			name = "API Token",
			description = "Run /generate_api_token in the Flipping Masterminds Discord to get your token. Join at discord.gg/VnsS2PP4Vt"
	)
	default String apiToken()
	{
		return "";
	}

	@ConfigItem(
			keyName = "showVolume",
			name = "Show Volume",
			description = "Display trade volume on each item row"
	)
	default boolean showVolume()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showPrices",
			name = "Show Prices",
			description = "Display the historical (snapshot) price and current (latest) price on each item row"
	)
	default boolean showPrices()
	{
		return true;
	}

	@ConfigItem(
			keyName = "autoRefresh",
			name = "Auto Refresh Prices",
			description = "Automatically fetch the latest prices on a timer (needed for price alerts to trigger)"
	)
	default boolean autoRefresh()
	{
		return true;
	}

	@ConfigItem(
			keyName = "autoRefreshMinutes",
			name = "Auto Refresh Interval (mins)",
			description = "How often to auto-refresh prices in minutes (minimum 2)"
	)
	default int autoRefreshMinutes()
	{
		return 5;
	}

	@ConfigItem(
			keyName = "geOverlay",
			name = "GE Price Overlay",
			description = "Highlight GE offer slots green (competitive) or red (outside market range)"
	)
	default boolean geOverlay()
	{
		return true;
	}

	@ConfigItem(
			keyName = "geLatestPrices",
			name = "GE Latest Prices",
			description = "Show latest wiki buy/sell price on the GE item examine text"
	)
	default boolean geLatestPrices()
	{
		return true;
	}
}

package com.flippingmasterminds;

import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;

import javax.imageio.ImageIO;
import javax.swing.*;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.net.URL;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.*;
import java.util.concurrent.*;

public class FlippingMastermindsPanel extends PluginPanel
{
    // ── Filter controls ───────────────────────────────────────────────────────
    private JComboBox<String> timeRangeDropdown;
    private JComboBox<String> performanceDropdown;
    private JTextField minPriceField;
    private JTextField maxPriceField;
    private JTextField minVolumeField;

    // ── Display toggles (driven by config, not checkboxes in the panel) ───────
    private boolean showVolume = true;
    private boolean showPrices = true;

    // ── Header widgets ────────────────────────────────────────────────────────
    private JButton refreshButton;
    private JLabel  lastUpdatedLabel;

    // ── Scrollable item list ──────────────────────────────────────────────────
    private JScrollPane viewportScroll;

    // ── Pagination bar (fixed at bottom of panel) ─────────────────────────────
    private JPanel paginationPanel;
    private JLabel pageInfoLabel;

    // ── Pagination state ──────────────────────────────────────────────────────
    private List<JPanel> resultPages = new ArrayList<>();
    private int currentPage = 0;

    // ── Data ──────────────────────────────────────────────────────────────────
    private Map<Integer, Long> baseline, day, week, month, year;
    private Map<Integer, ItemMeta> meta;
    private Map<Integer, Long> dayVolume    = Collections.emptyMap();
    private Map<Integer, Long> weekVolume   = Collections.emptyMap();
    private Map<Integer, Long> monthVolume  = Collections.emptyMap();
    private Map<Integer, Long> yearVolume   = Collections.emptyMap();

    // ── Image loading ─────────────────────────────────────────────────────────
    private final ConcurrentMap<Integer, ImageIcon> imageCache = new ConcurrentHashMap<>();
    private final Set<Integer> loadingSet = Collections.newSetFromMap(new ConcurrentHashMap<>());
    private final ExecutorService imageLoader;
    private final ImageIcon placeholderIcon;

    // ── Tab switching ────────────────────────────────────────────────────────
    private JPanel tabBar;
    private TabButton marketTabBtn;
    private TabButton alertsTabBtn;
    private TabButton buyLimitTabBtn;
    private CardLayout cardLayout;
    private JPanel cardPanel;
    private PriceAlertPanel alertPanel;
    private BuyLimitPanel buyLimitPanel;

    // ── Plugin callback ───────────────────────────────────────────────────────
    private Runnable onRefreshRequested;

    // ── Tab state ────────────────────────────────────────────────────────────
    private String activeTab = "market";

    // ── Constants ─────────────────────────────────────────────────────────────
    private static final int ITEMS_PER_PAGE = 20;
    private static final int ICON_SIZE      = 32;
    private static final int TAB_ICON_SIZE  = 22;
    private static final int NAME_LIMIT     = 20;
    private static final int MAX_PAGES      = 10;
    private static final int CARD_ARC       = 10;
    private static final DateTimeFormatter TIME_FMT = DateTimeFormatter.ofPattern("HH:mm:ss");

    // ── UI colours ───────────────────────────────────────────────────────────
    private static final Color BG_CARD       = new Color(30, 32, 42);
    private static final Color BORDER_SUBTLE = new Color(44, 47, 58);
    private static final Color BTN_HOVER_BG  = new Color(60, 60, 60);
    private static final Color BTN_PRESS_BG  = new Color(90, 90, 90);
    private static final int   BTN_ARC       = 6;

    // ─────────────────────────────────────────────────────────────────────────

    /**
     * Pass {@code false} to the PluginPanel super-constructor so RuneLite does
     * NOT wrap the entire panel in its own JScrollPane. This lets us control
     * the layout precisely: fixed header at top, scrollable item list in the
     * middle, fixed pagination bar at the bottom.
     */
    public FlippingMastermindsPanel()
    {
        super(false);

        imageLoader = Executors.newFixedThreadPool(3, r -> {
            Thread t = new Thread(r, "ge-panel-image-loader");
            t.setDaemon(true);
            return t;
        });

        placeholderIcon = makePlaceholderIcon(ICON_SIZE, ICON_SIZE);

        setLayout(new BorderLayout());

        // Top strip: social links + tab bar, always visible
        JPanel topStrip = new JPanel();
        topStrip.setLayout(new BoxLayout(topStrip, BoxLayout.Y_AXIS));
        topStrip.setOpaque(false);

        JPanel socialBar = new JPanel(new FlowLayout(FlowLayout.CENTER, 10, 4));
        socialBar.setOpaque(false);
        socialBar.add(createIconHoverButton("/discord_logo.png",
                "https://discord.gg/VnsS2PP4Vt", "Join our Discord!"));
        socialBar.add(createIconHoverButton("/github_logo.png",
                "https://github.com/ca-gray/Flipping-Masterminds", "View on GitHub!"));
        socialBar.add(createIconHoverButton("/oswiki_logo.png",
                "https://prices.runescape.wiki/osrs/", "View Wiki Prices!"));
        topStrip.add(socialBar);

        tabBar = new JPanel(new GridLayout(1, 3, 6, 0));
        tabBar.setBorder(BorderFactory.createEmptyBorder(2, 8, 2, 8));
        tabBar.setOpaque(false);
        marketTabBtn   = new TabButton(loadTabIcon("/market_logo.png"),   "Market");
        alertsTabBtn   = new TabButton(loadTabIcon("/tracking_logo.png"), "Alerts");
        buyLimitTabBtn = new TabButton(loadTabIcon("/buylimit_logo.png"), "Buy Limits");
        marketTabBtn.setTabActive(true);
        marketTabBtn.addActionListener(e -> switchTab("market"));
        alertsTabBtn.addActionListener(e -> switchTab("alerts"));
        buyLimitTabBtn.addActionListener(e -> switchTab("buylimits"));
        tabBar.add(marketTabBtn);
        tabBar.add(alertsTabBtn);
        tabBar.add(buyLimitTabBtn);
        topStrip.add(tabBar);

        add(topStrip, BorderLayout.NORTH);

        // Market view
        JPanel marketView = new JPanel(new BorderLayout());
        marketView.add(createHeaderPanel(),     BorderLayout.NORTH);
        marketView.add(createBodyPanel(),       BorderLayout.CENTER);
        marketView.add(createPaginationPanel(), BorderLayout.SOUTH);

        // Alerts view
        alertPanel = new PriceAlertPanel(imageCache, loadingSet, imageLoader, placeholderIcon);

        // Buy limits view
        buyLimitPanel = new BuyLimitPanel(imageCache, loadingSet, imageLoader, placeholderIcon);

        // Card layout to switch between them
        cardLayout = new CardLayout();
        cardPanel = new JPanel(cardLayout);
        cardPanel.add(marketView, "market");
        cardPanel.add(alertPanel, "alerts");
        cardPanel.add(buyLimitPanel, "buylimits");

        add(cardPanel, BorderLayout.CENTER);

        attachFilterListeners();
    }

    private ImageIcon loadTabIcon(String resourcePath)
    {
        try
        {
            URL res = getClass().getResource(resourcePath);
            if (res != null)
            {
                BufferedImage raw = ImageIO.read(res);
                Image scaled = raw.getScaledInstance(TAB_ICON_SIZE, TAB_ICON_SIZE, Image.SCALE_SMOOTH);
                return new ImageIcon(scaled);
            }
        }
        catch (IOException ignored) {}
        return null;
    }

    private void switchTab(String tab)
    {
        activeTab = tab;
        cardLayout.show(cardPanel, tab);
        marketTabBtn.setTabActive("market".equals(tab));
        alertsTabBtn.setTabActive("alerts".equals(tab));
        buyLimitTabBtn.setTabActive("buylimits".equals(tab));
        if ("alerts".equals(tab)) alertsTabBtn.setNotification(false);
        else if ("buylimits".equals(tab)) buyLimitTabBtn.setNotification(false);
    }

    public void notifyTab(String tab)
    {
        if ("alerts".equals(tab) && !"alerts".equals(activeTab))
        {
            alertsTabBtn.setNotification(true);
        }
        else if ("buylimits".equals(tab) && !"buylimits".equals(activeTab))
        {
            buyLimitTabBtn.setNotification(true);
        }
    }

    public PriceAlertPanel getAlertPanel()
    {
        return alertPanel;
    }

    public BuyLimitPanel getBuyLimitPanel()
    {
        return buyLimitPanel;
    }

    // ── Public API ────────────────────────────────────────────────────────────

    public void refreshButtonReset()
    {
        refreshButton.setEnabled(true);
        refreshButton.setText("⟳ Refresh");
        lastUpdatedLabel.setText("Fetch failed");
        lastUpdatedLabel.setForeground(new Color(220, 50, 50));
    }

    public void setOnRefreshRequested(Runnable callback)
    {
        this.onRefreshRequested = callback;
    }

    public void applyConfig(boolean showVolume, boolean showPrices)
    {
        boolean changed = (this.showVolume != showVolume) || (this.showPrices != showPrices);
        this.showVolume = showVolume;
        this.showPrices = showPrices;
        if (changed && baseline != null && meta != null)
        {
            rebuildResults();
        }
    }

    // ── Panel builders ────────────────────────────────────────────────────────

    private JPanel createHeaderPanel()
    {
        JPanel headerPanel = new JPanel();
        headerPanel.setLayout(new BoxLayout(headerPanel, BoxLayout.Y_AXIS));

        // Filter grid
        JPanel filterPanel = new JPanel(new GridBagLayout());
        filterPanel.setBorder(BorderFactory.createEmptyBorder(5, 5, 5, 5));

        // Label constraint: tight, no horizontal grow
        GridBagConstraints lbl = new GridBagConstraints();
        lbl.anchor  = GridBagConstraints.WEST;
        lbl.insets  = new Insets(2, 2, 2, 4);
        lbl.gridx   = 0;
        lbl.gridy   = 0;
        lbl.fill    = GridBagConstraints.NONE;
        lbl.weightx = 0.0;

        // Field constraint: fills remaining width
        GridBagConstraints fld = new GridBagConstraints();
        fld.anchor  = GridBagConstraints.WEST;
        fld.insets  = new Insets(2, 0, 2, 2);
        fld.gridx   = 1;
        fld.gridy   = 0;
        fld.fill    = GridBagConstraints.HORIZONTAL;
        fld.weightx = 1.0;

        // Row 0 – Time Range
        filterPanel.add(new JLabel("Time Range:"), lbl);
        timeRangeDropdown = new JComboBox<>(new String[]{"Day", "Week", "Month", "Year"});
        filterPanel.add(timeRangeDropdown, fld);

        // Row 1 – Performance
        lbl.gridy++; fld.gridy++;
        filterPanel.add(new JLabel("Performance:"), lbl);
        performanceDropdown = new JComboBox<>(
                new String[]{"Top Performers", "Underperformers"});
        filterPanel.add(performanceDropdown, fld);

        // Row 2 – Min Price
        lbl.gridy++; fld.gridy++;
        filterPanel.add(new JLabel("Min Price:"), lbl);
        minPriceField = new JTextField("1");
        filterPanel.add(minPriceField, fld);

        // Row 3 – Max Price
        lbl.gridy++; fld.gridy++;
        filterPanel.add(new JLabel("Max Price:"), lbl);
        maxPriceField = new JTextField();
        maxPriceField.setToolTipText("Leave empty for no upper limit");
        filterPanel.add(maxPriceField, fld);

        // Row 4 – Min Volume
        lbl.gridy++; fld.gridy++;
        filterPanel.add(new JLabel("Min Volume:"), lbl);
        minVolumeField = new JTextField("0");
        minVolumeField.setToolTipText("Minimum total trades in the selected time window");
        filterPanel.add(minVolumeField, fld);

        headerPanel.add(filterPanel);

        // Refresh row
        JPanel refreshRow = new JPanel(new FlowLayout(FlowLayout.CENTER, 8, 4));

        refreshButton = new JButton("⟳ Refresh");
        refreshButton.setToolTipText("Re-fetch latest GE price data");
        refreshButton.setFocusPainted(false);
        refreshButton.addActionListener(e -> {
            refreshButton.setEnabled(false);
            refreshButton.setText("Fetching…");
            if (onRefreshRequested != null) onRefreshRequested.run();
        });
        refreshRow.add(refreshButton);

        lastUpdatedLabel = new JLabel("Not yet loaded");
